const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',leads:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M21 21v-3a6 6 0 0 0-3-5"/>',campaigns:'<path d="m3 11 18-8-8 18-3-8-7-2ZM10 13 21 3"/>',workflow:'<rect x="8" y="2" width="8" height="5" rx="1"/><rect x="2" y="17" width="7" height="5" rx="1"/><rect x="15" y="17" width="7" height="5" rx="1"/><path d="M12 7v5H5v5M12 12h7v5"/>',emails:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',inbox:'<path d="M3 3h18v18H3zM3 14h5l2 3h4l2-3h5"/>',meetings:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18M8 15h3"/>',pipeline:'<path d="M4 3v18M12 3v18M20 3v18M2 7h4M10 12h4M18 6h4"/>',analytics:'<path d="M3 3v18h18M7 17v-6M12 17V7M17 17V3"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.overview}</svg>`;
const seed={leads:[{id:1,name:'Sarah Chen',email:'sarah@northstar.example',company:'Northstar Studio',title:'Head of Operations',status:'Qualified',industry:'Design & creative',confidence:92},{id:2,name:'James Wilson',email:'james@relay.example',company:'Relay Technologies',title:'VP of Sales',status:'Contacted',industry:'Software',confidence:88},{id:3,name:'Aisha Khan',email:'aisha@bloom.example',company:'Bloom Commerce',title:'Founder',status:'New',industry:'E-commerce',confidence:0},{id:4,name:'Daniel Park',email:'daniel@orbit.example',company:'Orbit Labs',title:'Co-founder',status:'Meeting booked',industry:'Software',confidence:95},{id:5,name:'Emma Davis',email:'emma@forma.example',company:'Forma Collective',title:'Managing Director',status:'New',industry:'Consulting',confidence:0},{id:6,name:'Omar Hassan',email:'omar@atlas.example',company:'Atlas Digital',title:'Sales Director',status:'Replied',industry:'Marketing',confidence:86}],campaigns:[{id:1,name:'A better workflow for growing teams',audience:'Software & creative agencies',status:'Active',tone:'Friendly',offer:'Automate reporting so your team can focus on clients.',ids:[1,2,3,4],sent:2,replies:1},{id:2,name:'More conversations, less admin',audience:'Sales leaders at digital companies',status:'Draft',tone:'Professional',offer:'Bring outreach and customer conversations into one workspace.',ids:[5,6],sent:0,replies:0}],drafts:[],meetings:[{id:1,lead:4,date:'2026-10-12',time:'14:30',duration:'30',status:'Scheduled'}],messages:[{lead:1,type:'Interested',text:'Hi Bilal, this sounds relevant to what we are working on. Could we find 20 minutes next week to talk through the workflow?',replies:[]},{lead:6,type:'Question',text:'Thanks for reaching out. How would this work with our existing sales process? Do you support a review step before emails are sent?',replies:[]}],settings:{company:'Bilal Studio',sender:'Bilal Malik',offer:'Help growing teams automate repetitive reporting and sales administration.',timezone:'Asia/Karachi',limit:50},activity:[]};
let state;try{state=JSON.parse(localStorage.getItem('salesway-data'))||structuredClone(seed)}catch(e){state=structuredClone(seed)}let storageOK=true,selectedThread=0,search='',filter='All',processing=false,stage=-1;
function save(){try{localStorage.setItem('salesway-data',JSON.stringify(state))}catch(e){storageOK=false;toast('Changes stay in this session: browser storage is unavailable.')}}
let toastTimer;function toast(s){$('#toast').innerHTML=`<span class="toast-icon" aria-hidden="true">${/unavailable|first|stopped|limit|choose|already|overlap/i.test(s)?'!':'✓'}</span><span class="toast-copy"><strong>Workspace update</strong>${esc(s)}</span><button aria-label="Dismiss notification" onclick="$('#toast').classList.remove('show')">×</button>`;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function record(s){state.activity.unshift({text:s,time:'Just now'});save()}
function badge(s){return `<span class="badge ${['New','Draft','Needs review'].includes(s)?'warn':''}">${esc(s)}</span>`}
function person(l){return `<div class="person"><span class="initials">${esc(l.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><strong>${esc(l.name)}</strong><small>${esc(l.email)}</small></div></div>`}
const pages=['overview','leads','campaigns','workflow','emails','inbox','meetings','followups','pipeline','analytics','settings'],names={overview:'Overview',leads:'Leads',campaigns:'Campaigns',workflow:'AI workflow',emails:'Email review',inbox:'Inbox',meetings:'Meetings',followups:'Follow-ups',pipeline:'CRM pipeline',analytics:'Analytics',settings:'Settings'};
$('#nav').innerHTML=pages.map(p=>`<a href="#${p}" data-page="${p}" title="${names[p]}">${icon(p)}<span class="nav-text">${names[p]}</span></a>`).join('');
function heading(title,desc,actions='',eyebrow='YOUR WORKSPACE'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function metrics(items){return `<div class="metrics">${items.map(([label,value,note,i])=>`<div class="card tilt"><div class="metric-top">${label}<span class="icon-tile">${icon(i)}</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`).join('')}</div>`}
function leadTable(ls,actions=true){return ls.length?`<div class="table-wrap"><table><thead><tr><th>Contact</th><th>Company</th><th>Status</th><th>Research</th>${actions?'<th></th>':''}</tr></thead><tbody>${ls.map(l=>`<tr><td>${person(l)}</td><td>${esc(l.company)}<small style="display:block;margin-top:5px">${esc(l.title)}</small></td><td>${badge(l.status)}</td><td>${l.confidence?`${l.confidence}% · demo`:'Not researched'}</td>${actions?`<td><button class="link" onclick="leadDetail(${l.id})">View ↗</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>No leads here yet</h3><p>Add a contact or import a CSV to get started.</p><button onclick="addLead()">Add a lead</button></div>'}
function chart(){return `<div class="chart">${[45,67,55,82,71,95,62].map((h,i)=>`<div class="bar-group"><div class="bar" style="height:${h}%" title="Illustrative outreach volume"></div><div class="bar alt" style="height:${h*.45}%" title="Illustrative engagement"></div><small>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</small></div>`).join('')}</div><div class="legend"><span><i></i>Outreach</span><span><i class="light"></i>Engagement</span><span>Illustrative demo chart</span></div>`}
function overview(){return heading('Room for better conversations.','Your leads, outreach, and next steps. Thoughtfully connected.',`<button onclick="addLead()">+ Add lead</button><button class="primary" onclick="campaignForm()">Create campaign ↗</button>`,'FRIDAY, 9 OCTOBER · DEMO')+metrics([['Total leads',state.leads.length,'In your demo workspace','leads'],['Active campaigns',state.campaigns.filter(c=>c.status==='Active').length,'Ready to build momentum','campaigns'],['Conversations',state.messages.length,'Replies worth your attention','inbox'],['Meetings booked',state.meetings.filter(m=>m.status==='Scheduled').length,'Your next opportunities','meetings']])+`<div class="hero-note"><div><h3>Your next good conversation starts with a lead.</h3><p>Research your prospects, review the message, and make it personal.</p></div><button class="primary" onclick="location.hash='workflow'">Open AI workflow ↗</button></div><div class="grid2"><section class="card"><div class="card-head"><h2>Outreach at a glance</h2><span class="badge">Sample week</span></div>${chart()}</section><section class="card"><div class="card-head"><h2>What needs your attention</h2><button class="link" onclick="location.hash='inbox'">View inbox ↗</button></div><div class="activity"><span class="icon-tile">${icon('inbox')}</span><div><p><strong>${state.messages.length} conversations</strong> waiting for a next step</p><small>Review replies and book a meeting</small></div></div><div class="activity"><span class="icon-tile">${icon('emails')}</span><div><p><strong>${state.drafts.filter(d=>d.status==='Needs review').length} email drafts</strong> ready for review</p><small>Your voice. A little help from AI.</small></div></div><div class="activity"><span class="icon-tile">${icon('workflow')}</span><div><p><strong>${state.leads.filter(l=>!l.confidence).length} leads</strong> ready for research</p><small>Build context before reaching out</small></div></div></section></div><section class="card"><div class="card-head"><h2>People in your pipeline</h2><button class="link" onclick="location.hash='leads'">All leads ↗</button></div>${leadTable(state.leads.slice(0,4))}</section>`}
function leads(){return heading('Every opportunity starts here.','Keep the people behind your pipeline in focus.',`<button onclick="importForm()">Import CSV</button><button class="primary" onclick="addLead()">+ Add lead</button>`,'CONTACTS & COMPANIES')+`<div class="card"><div class="filters"><input id="search" aria-label="Search leads" placeholder="Search name, email, or company…" value="${esc(search)}"><select id="filter" aria-label="Filter by status">${['All','New','Contacted','Replied','Qualified','Meeting booked','Won','Lost','Unsubscribed'].map(s=>`<option ${s===filter?'selected':''}>${s}</option>`).join('')}</select><button onclick="exportLeads()">Export CSV ↓</button></div><div id="lead-results">${filteredLeads()}</div></div>`}
function filteredLeads(){return leadTable(state.leads.filter(l=>(filter==='All'||l.status===filter)&&`${l.name} ${l.company} ${l.email}`.toLowerCase().includes(search.toLowerCase())))}
function campaigns(){return heading('Outreach with intention.','Give every campaign a clear audience, a useful offer, and your own voice.',`<button class="primary" onclick="campaignForm()">+ New campaign</button>`,'CAMPAIGNS')+`<div class="campaigns">${state.campaigns.map(c=>`<article class="card campaign tilt"><div class="card-head">${badge(c.status)}<button class="link" onclick="campaignForm(${c.id})">Edit ↗</button></div><h3>${esc(c.name)}</h3><p>${esc(c.audience)}</p><div class="mini-stats"><div><strong>${c.ids.length}</strong><small>Leads</small></div><div><strong>${c.sent}</strong><small>Demo sends</small></div><div><strong>${c.replies}</strong><small>Sample replies</small></div></div><small>${esc(c.tone)} tone · Human review enabled</small><div class="track"><i style="width:${c.ids.length?Math.min(100,c.sent/c.ids.length*100):0}%"></i></div><div class="actions"><button class="primary" onclick="location.hash='workflow'">Prepare outreach ↗</button><button onclick="toggleCampaign(${c.id})">${c.status==='Active'?'Pause':'Activate'}</button></div></article>`).join('')}</div>`}
function workflow(){return heading('A thoughtful first impression.','Turn a contact into a researched, personalized email. One clear step at a time.','','AI WORKFLOW')+`<div class="notice">This is a simulated AI workflow. Research is fictional sample content, and no AI service is called. You review every draft before a demo send.</div><section class="card"><div class="form-grid"><div><label for="workflow-lead">Choose a lead</label><select id="workflow-lead" ${processing?'disabled':''}>${state.leads.filter(l=>!['Unsubscribed','Lost'].includes(l.status)).map(l=>`<option value="${l.id}">${esc(l.name)} · ${esc(l.company)}</option>`).join('')}</select></div><div><label for="workflow-campaign">Campaign context</label><select id="workflow-campaign" ${processing?'disabled':''}>${state.campaigns.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div></div><div class="steps">${['Enrich contact','Research company','Write email','Human review'].map((s,i)=>`<div class="step ${stage>=i?'active':''}"><strong>${stage>i?'✓':i+1} · ${s}</strong><span>${stage>i?'Completed (demo)':stage===i?'Processing…':'Waiting'}</span></div>`).join('')}</div><div class="actions"><button class="primary" id="run-workflow" ${processing||!state.leads.length||!state.campaigns.length?'disabled':''} onclick="runWorkflow()">${processing?'<span class="spinner" aria-hidden="true"></span>Preparing your draft…':'Run demo workflow ↗'}</button><small>Approx. 4 seconds · No external calls</small></div><div id="workflow-result">${processing?'<div class="research-preview" style="margin-top:24px" aria-label="Loading research"><article><div class="skeleton"></div><div class="skeleton skeleton-block"></div></article><article><div class="skeleton"></div><div class="skeleton skeleton-block"></div></article></div>':''}</div></section>`}
function emails(){return heading('Your voice. Ready for review.','Fine-tune the message before starting a conversation.','','EMAIL REVIEW')+`<div class="notice">Approving or sending here updates demo records only. No real email leaves this workspace.</div>${state.drafts.length?state.drafts.map(d=>{let l=state.leads.find(x=>x.id===d.lead);return `<section class="card" style="margin-bottom:20px"><div class="card-head">${person(l)}${badge(d.status)}</div><h3>${esc(d.subject)}</h3><p class="email-body">${esc(d.body)}</p><div class="actions"><button onclick="editDraft(${d.id})" ${d.status==='Sent'?'disabled':''}>Edit draft</button><button onclick="approveDraft(${d.id})" ${d.status!=='Needs review'?'disabled':''}>Approve</button><button class="primary" onclick="sendDraft(${d.id})" ${d.status!=='Approved'?'disabled':''}>${d.status==='Sent'?'Demo sent ✓':'Send demo email ↗'}</button></div></section>`}).join(''):`<section class="card empty"><h2>A blank page, a good beginning.</h2><p>Run the AI workflow to create your first personalized draft.</p><button class="primary" onclick="location.hash='workflow'">Prepare an email ↗</button></section>`}` }
function inbox(){let m=state.messages[selectedThread],l=m&&state.leads.find(x=>x.id===m.lead);return heading('Keep the conversation going.','Read the reply, understand the intent, and take the right next step.','','CONVERSATIONS')+`<div class="inbox"><section>${state.messages.map((x,i)=>`<button class="thread ${selectedThread===i?'selected':''}" onclick="selectedThread=${i};render()">${person(state.leads.find(l=>l.id===x.lead))}<p>${esc(x.text.slice(0,85))}…</p>${badge(x.type)}</button>`).join('')}</section><section class="card">${m?`<div class="card-head">${person(l)}${badge(m.type)}</div><small>Fictional incoming reply · Demo conversation</small><div class="message">${esc(m.text)}</div>${m.replies.map(r=>`<div class="message"><small>You · Saved demo reply</small><br>${esc(r)}</div>`).join('')}<label for="reply">Your reply</label><textarea id="reply" placeholder="Write a thoughtful response…"></textarea><div class="form-actions"><button onclick="suggestReply()">Suggest reply ✧</button><button class="primary" onclick="saveReply()">Save demo reply ↗</button></div><hr style="border:0;border-top:1px solid var(--border);margin:24px 0"><div class="actions"><button onclick="bookingForm(${l.id})">Book a meeting</button><button onclick="followupForm(${l.id})">Schedule follow-up</button><button onclick="unsubscribe(${l.id})">Stop outreach</button></div>`:'<div class="empty">No conversations yet.</div>'}</section></div>`}
function meetings(){return heading('Make time for what matters.','A clear view of your upcoming customer conversations.',`<button class="primary" onclick="bookingForm()">+ Book demo meeting</button>`,'MEETINGS')+`<div class="notice">Bookings are saved locally. No calendar invitations or availability checks are performed. Times use ${esc(state.settings.timezone)}.</div><section class="card">${state.meetings.length?state.meetings.map(m=>{const l=state.leads.find(x=>x.id===m.lead);return `<div class="meeting"><div class="date-tile">${new Date(m.date+'T12:00:00').toLocaleDateString('en',{month:'short'})}<strong>${Number(m.date.slice(-2))}</strong></div><div><h3>Discovery call · ${esc(l.company)}</h3><small>${esc(l.name)} · ${esc(m.time)} · ${esc(m.duration)} minutes</small><p style="margin:6px 0">${badge(m.status)}</p></div><div class="actions"><button onclick="bookingForm(${m.lead},${m.id})" ${m.status==='Cancelled'?'disabled':''}>Reschedule</button><button onclick="cancelMeeting(${m.id})" ${m.status==='Cancelled'?'disabled':''}>Cancel</button></div></div>`}).join(''):'<div class="empty"><h3>Your calendar has room.</h3><p>Book a demo meeting from an interested conversation.</p></div>'}</section>`}
function followups(){let ls=state.leads.filter(l=>l.followup);return heading('A timely, thoughtful nudge.','Keep track of your next touchpoint without losing the conversation.','','FOLLOW-UPS')+`<div class="notice">Follow-ups are local plans. This prototype does not run background jobs or send scheduled emails.</div><section class="card">${ls.length?ls.map(l=>`<div class="meeting"><div>${person(l)}<p>Next touchpoint: ${esc(l.followup)}</p></div><div class="actions"><button onclick="followupForm(${l.id})">Reschedule</button><button onclick="delete state.leads.find(x=>x.id===${l.id}).followup;save();render();toast('Follow-up cancelled.')">Cancel follow-up</button></div></div>`).join(''):'<div class="empty"><h3>All caught up.</h3><p>Schedule a next touchpoint from a conversation in your inbox.</p><button onclick="location.hash=\'inbox\'">Open inbox ↗</button></div>'}</section>`}
function pipeline(){let cols=[['New',['New']],['In conversation',['Contacted','Replied']],['Qualified',['Qualified','Meeting booked']],['Closed',['Won','Lost','Unsubscribed']]];return heading('See the next step clearly.','Move opportunities forward, with the full conversation in view.','','CRM PIPELINE')+`<div class="board">${cols.map(([n,status])=>`<section class="column"><h3>${n}<span>${state.leads.filter(l=>status.includes(l.status)).length}</span></h3>${state.leads.filter(l=>status.includes(l.status)).map(l=>`<article class="deal"><h3>${esc(l.company)}</h3><p>${esc(l.name)} · ${esc(l.title)}</p>${badge(l.status)}<label class="muted" style="font-size:11px;margin:12px 0 0" for="stage-${l.id}">Move to stage</label><select id="stage-${l.id}" onchange="moveLead(${l.id},this.value)">${['New','Contacted','Replied','Qualified','Meeting booked','Won','Lost','Unsubscribed'].map(s=>`<option ${s===l.status?'selected':''}>${s}</option>`).join('')}</select></article>`).join('')||'<p class="muted">No opportunities in this stage.</p>'}</section>`).join('')}</div>`}
function analytics(){let sent=state.campaigns.reduce((s,c)=>s+c.sent,0);return heading('Understand your momentum.','Look beyond activity. Find the conversations that move your business forward.',`<button onclick="exportReport()">Export report ↓</button>`,'ANALYTICS')+metrics([['Demo emails sent',sent,'Sample baseline + local demo sends','emails'],['Sample replies',state.messages.length,'Fictional inbox conversations','inbox'],['Scheduled meetings',state.meetings.filter(m=>m.status==='Scheduled').length,'Saved in this workspace','meetings'],['Drafts prepared',state.drafts.length,'From the simulated workflow','workflow']])+`<div class="grid2"><section class="card"><div class="card-head"><h2>Weekly activity</h2>${badge('Illustrative')}</div>${chart()}</section><section class="card"><h2>Your local activity</h2>${state.activity.length?state.activity.slice(0,8).map(a=>`<div class="activity"><span class="dot"></span><div><p>${esc(a.text)}</p><small>${esc(a.time)}</small></div></div>`).join(''):'<p>No local actions yet. Prepare a draft or add a lead to start your activity history.</p>'}</section></div><section class="card"><h2>Campaign performance</h2><div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Leads</th><th>Demo sends</th><th>Sample replies</th><th>Status</th></tr></thead><tbody>${state.campaigns.map(c=>`<tr><td>${esc(c.name)}</td><td>${c.ids.length}</td><td>${c.sent}</td><td>${c.replies}</td><td>${badge(c.status)}</td></tr>`).join('')}</tbody></table></div></section>`}
function settings(){return heading('Make this workspace yours.','Set your business context and keep your outreach consistent.','','WORKSPACE SETTINGS')+`<form class="card" id="settings-form"><h2>Business & sending preferences</h2><div class="form-grid">${field('Company name','company',state.settings.company)}${field('Sender name','sender',state.settings.sender)}<div class="field span2"><label for="offer">Your product or service</label><textarea name="offer" id="offer" required>${esc(state.settings.offer)}</textarea></div>${field('Timezone','timezone',state.settings.timezone)}${field('Daily demo send limit','limit',state.settings.limit,'number','min="1" max="500"')}</div><div class="notice">Email, calendar, and CRM providers are not connected in this prototype. All records stay in your browser.</div><div class="form-actions"><button type="button" onclick="resetDemo()">Reset demo workspace</button><button class="primary">Save preferences</button></div></form>`}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" required ${extra}></div>`}
function render(){closeDropdown();let p=location.hash.slice(1)||'overview';if(!pages.includes(p))p='overview';$('#main').innerHTML=({overview,leads,campaigns,workflow,emails,inbox,meetings,followups,pipeline,analytics,settings}[p])()+`<footer><span>Salesway · A calmer way to grow.</span><span>Interactive prototype · ${storageOK?'Saved locally':'Session only'}</span></footer>`;document.title=names[p]+' · Salesway';$('#breadcrumb').innerHTML=`Workspace <span>/</span> ${names[p]}`;document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===p);if(a.dataset.page===p)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(p==='leads'){ $('#search').oninput=e=>{search=e.target.value;$('#lead-results').innerHTML=filteredLeads()};$('#filter').onchange=e=>{filter=e.target.value;$('#lead-results').innerHTML=filteredLeads()}}if(p==='settings')$('#settings-form').onsubmit=e=>{e.preventDefault();state.settings=Object.fromEntries(new FormData(e.target));save();toast('Workspace preferences saved locally.')};bindTilt();enhanceSelects()}
function modal(title,html,onSubmit){closeDropdown();closeCalendar();$('#modal-body').innerHTML=`<div class="modal-head"><h2 id="dialog-title">${title}</h2><button aria-label="Close dialog" onclick="closeModal()">×</button></div>${html}`;$('#modal').showModal();const form=$('#modal form');if(form)form.onsubmit=async e=>{e.preventDefault();await onSubmit(new FormData(form),form)};enhanceSelects($('#modal'));enhanceDates($('#modal'))}
function addLead(id){let l=state.leads.find(x=>x.id===id)||{};modal(id?'Edit contact':'A new connection',`<form><div class="form-grid">${field('Full name','name',l.name)}${field('Email address','email',l.email,'email')}${field('Company','company',l.company)}${field('Job title','title',l.title||'')}${field('Industry','industry',l.industry||'')}</div><p id="form-error" class="error" role="alert"></p><div class="form-actions"><button type="button" onclick="$('#modal').close()">Cancel</button><button class="primary">Save lead</button></div></form>`,d=>{let v=Object.fromEntries(d);v.email=v.email.trim().toLowerCase();if(state.leads.some(x=>x.id!==id&&x.email.toLowerCase()===v.email)){ $('#form-error').textContent='This email already exists in your workspace.';return}if(id)Object.assign(l,v);else state.leads.push({...v,id:Date.now(),status:'New',confidence:0});record(id?'Contact updated':'New lead added');$('#modal').close();render();toast('Contact saved locally.')})}
function leadDetail(id){const l=state.leads.find(x=>x.id===id);modal('Contact profile',`${person(l)}<p><strong>${esc(l.company)}</strong><br>${esc(l.title)} · ${esc(l.industry)}</p>${badge(l.status)}${l.research?`<h3 style="margin-top:24px">Company context</h3><p>${esc(l.research.summary)}</p><p>${esc(l.research.opportunity)}</p><small>${esc(l.research.source)}</small>`:''}<div class="notice" style="margin-top:20px">${l.confidence?`Demo research confidence: ${l.confidence}%. Sample profile, not verified information.`:'This contact has not been researched yet.'}${l.followup?`<br>Follow-up: ${esc(l.followup)}`:''}</div><div class="actions"><button onclick="$('#modal').close();addLead(${id})">Edit contact</button><button class="primary" onclick="$('#modal').close();location.hash='workflow'">Prepare outreach ↗</button><button onclick="deleteLead(${id})">Delete</button></div>`)}
function deleteLead(id){modal('Delete this lead?',`<p>This removes the contact and their related demo drafts, meetings, and conversations.</p><div class="actions"><button onclick="$('#modal').close()">Keep lead</button><button class="primary" onclick="confirmDelete(${id})">Delete lead</button></div>`)}
function confirmDelete(id){state.leads=state.leads.filter(l=>l.id!==id);state.drafts=state.drafts.filter(d=>d.lead!==id);state.meetings=state.meetings.filter(m=>m.lead!==id);state.messages=state.messages.filter(m=>m.lead!==id);state.campaigns.forEach(c=>c.ids=c.ids.filter(x=>x!==id));selectedThread=0;record('Lead removed from workspace');$('#modal').close();render();toast('Lead deleted.')}
function campaignForm(id){let c=state.campaigns.find(c=>c.id===id)||{};modal(id?'Edit campaign':'Give your campaign direction',`<form>${field('Campaign name','name',c.name)}${field('Target audience','audience',c.audience)}<div class="field"><label for="campaign-offer">Value proposition</label><textarea id="campaign-offer" name="offer" required>${esc(c.offer||state.settings.offer)}</textarea></div><div class="field"><label for="tone">Tone</label><select id="tone" name="tone">${['Friendly','Professional','Casual'].map(t=>`<option ${t===c.tone?'selected':''}>${t}</option>`).join('')}</select></div><label>Campaign leads</label><div style="max-height:180px;overflow:auto;margin:15px 0">${state.leads.filter(l=>l.status!=='Unsubscribed').map(l=>`<label style="display:flex;gap:10px;align-items:center"><input style="width:auto" type="checkbox" name="ids" value="${l.id}" ${(c.ids||[]).includes(l.id)?'checked':''}>${esc(l.name)} · ${esc(l.company)}</label>`).join('')}</div><p class="error" id="form-error"></p><div class="form-actions"><button type="button" onclick="$('#modal').close()">Cancel</button><button class="primary">Save campaign</button></div></form>`,d=>{let ids=d.getAll('ids').map(Number);if(!ids.length){$('#form-error').textContent='Choose at least one lead for this campaign.';return}let v={name:d.get('name'),audience:d.get('audience'),offer:d.get('offer'),tone:d.get('tone'),ids};if(id)Object.assign(c,v);else state.campaigns.push({...v,id:Date.now(),status:'Draft',sent:0,replies:0});record('Campaign saved');$('#modal').close();render();toast('Campaign saved locally.')})}
function toggleCampaign(id){let c=state.campaigns.find(c=>c.id===id);c.status=c.status==='Active'?'Paused':'Active';record(`Campaign ${c.status.toLowerCase()}`);render();toast('Campaign status updated.')}
async function runWorkflow(){const l=state.leads.find(l=>l.id===Number($('#workflow-lead').value)),c=state.campaigns.find(c=>c.id===Number($('#workflow-campaign').value));if(!l||!c)return;if(!c.ids.includes(l.id)){toast('Choose a lead assigned to this campaign, or edit the campaign first.');return}processing=true;for(stage=0;stage<4;stage++){if(location.hash==='#workflow'||!location.hash)render();await new Promise(r=>setTimeout(r,900))}l.confidence=l.confidence||87;l.research={summary:`Fictional demo context: ${l.company} is a growing team in ${l.industry}.`,opportunity:c.offer,source:'Simulated profile; no external verification'};state.drafts.push({id:Date.now(),lead:l.id,campaign:c.id,status:'Needs review',subject:`A simpler workflow for ${l.company}`,body:`Hi ${l.name.split(' ')[0]},\n\nAs ${l.title.toLowerCase()} at ${l.company}, you likely balance a lot of moving pieces.\n\n${c.offer}\n\nWould a short conversation next week be useful to see whether this fits your team?\n\nBest,\n${state.settings.sender}`});processing=false;stage=-1;record(`Demo research and email draft prepared for ${l.name}`);if(location.hash==='#workflow'){render();$('#workflow-result').innerHTML='<div class="notice" style="margin-top:24px"><strong>✓ Your draft is ready.</strong> Demo contact context and email saved for human review. <button class="link" onclick="location.hash=\'emails\'">Review email ↗</button></div>'}toast('Demo draft created. Review it in Email review.')}
function editDraft(id){let d=state.drafts.find(d=>d.id===id);modal('Make it sound like you',`<form>${field('Subject','subject',d.subject)}<label for="email-body">Email body</label><textarea id="email-body" name="body" required rows="10">${esc(d.body)}</textarea><div class="form-actions"><button class="primary">Save draft</button></div></form>`,f=>{d.subject=f.get('subject');d.body=f.get('body');d.status='Needs review';save();$('#modal').close();render();toast('Draft updated. Review and approve again.')})}
function approveDraft(id){state.drafts.find(d=>d.id===id).status='Approved';record('Email draft approved');render();toast('Draft approved for a demo send.')}
function sendDraft(id){const d=state.drafts.find(d=>d.id===id),l=state.leads.find(l=>l.id===d.lead),c=state.campaigns.find(c=>c.id===d.campaign);if(d.status!=='Approved')return;if(['Unsubscribed','Lost'].includes(l.status)){toast('Outreach is stopped for this contact.');return}if(c.status!=='Active'){toast('Activate this campaign before sending a demo email.');return}const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Karachi'});if(state.drafts.filter(x=>x.sentDate===today).length>=Number(state.settings.limit)){toast('Daily demo sending limit reached.');return}d.status='Sent';d.sentDate=today;c.sent++;if(l.status==='New')l.status='Contacted';record(`Demo email sent to ${l.name}`);render();toast('Demo send recorded. No real email was sent.')}
function suggestReply(){const m=state.messages[selectedThread],l=state.leads.find(l=>l.id===m.lead);$('#reply').value=`Hi ${l.name.split(' ')[0]},\n\n${m.type==='Interested'?'Thanks for your interest! I would be happy to walk through the workflow. What time works well for you next week?':'Yes, a human review step is part of the workflow. Could you share a little about your current process so we can discuss the right fit?'}\n\nBest,\n${state.settings.sender}`}
function saveReply(){let text=$('#reply').value.trim(),m=state.messages[selectedThread],l=state.leads.find(l=>l.id===m.lead);if(!text){toast('Write a reply first.');$('#reply').focus();return}if(l.status==='Unsubscribed'){toast('This contact has stopped outreach.');return}m.replies.push(text);record('Demo reply saved');render();toast('Reply saved locally. No message sent.')}
function unsubscribe(id){state.leads.find(l=>l.id===id).status='Unsubscribed';delete state.leads.find(l=>l.id===id).followup;record('Outreach stopped for contact');render();toast('Contact marked unsubscribed; demo sends are blocked.')}
function followupForm(id){modal('Plan a thoughtful follow-up',`<form>${field('Follow-up date','date','','date',`min="${new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Karachi'})}"`)}<div class="form-actions"><button class="primary">Schedule demo follow-up</button></div></form>`,d=>{let l=state.leads.find(l=>l.id===id);if(l.status==='Unsubscribed'){toast('Outreach is stopped for this contact.');return}l.followup=d.get('date');record(`Follow-up scheduled for ${l.name}`);$('#modal').close();render();toast('Follow-up saved locally. No background email scheduled.')})}
function bookingForm(lead,id){const m=state.meetings.find(m=>m.id===id)||{};modal(id?'Reschedule conversation':'Make room for a conversation',`<form><div class="field"><label for="booking-lead">Contact</label><select id="booking-lead" name="lead">${state.leads.map(l=>`<option value="${l.id}" ${l.id===lead?'selected':''}>${esc(l.name)} · ${esc(l.company)}</option>`).join('')}</select></div><div class="form-grid">${field('Date','date',m.date||'','date',`min="${new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Karachi'})}"`)}${field('Time','time',m.time||'10:00','time')}<div class="field"><label for="duration">Duration</label><select id="duration" name="duration">${[15,20,30,45,60].map(x=>`<option value="${x}" ${String(x)===(m.duration||'30')?'selected':''}>${x} minutes</option>`).join('')}</select></div></div><p class="error" id="form-error"></p><small>Timezone: ${esc(state.settings.timezone)} · Local demo booking</small><div class="form-actions"><button class="primary">Save demo booking</button></div></form>`,d=>{let v=Object.fromEntries(d);v.lead=Number(v.lead);if(state.meetings.some(x=>x.id!==id&&x.status==='Scheduled'&&x.date===v.date&&Math.abs((Number(x.time.slice(0,2))*60+Number(x.time.slice(3)))-(Number(v.time.slice(0,2))*60+Number(v.time.slice(3))))<Math.max(Number(x.duration),Number(v.duration)))){$('#form-error').textContent='This time overlaps another demo meeting. Choose another slot.';return}if(id)Object.assign(m,v);else state.meetings.push({...v,id:Date.now(),status:'Scheduled'});const l=state.leads.find(l=>l.id===v.lead);l.status='Meeting booked';delete l.followup;record(`Meeting booked with ${l.name}`);$('#modal').close();render();toast('Demo booking saved. No calendar invitation sent.')})}
function cancelMeeting(id){state.meetings.find(m=>m.id===id).status='Cancelled';record('Demo meeting cancelled');render();toast('Meeting cancelled locally.')}
function moveLead(id,status){let l=state.leads.find(l=>l.id===id);l.status=status;if(['Won','Lost','Unsubscribed','Meeting booked'].includes(status))delete l.followup;record(`${l.name} moved to ${status}`);render()}
function csvRows(text){let rows=[],row=[],value='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(value);value=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(x=>x.trim()))rows.push(row);row=[];value=''}else value+=c}if(quoted)throw Error('Unclosed quotation in CSV.');row.push(value);if(row.some(x=>x.trim()))rows.push(row);return rows}
function importForm(){modal('Bring your leads with you',`<form><p>Upload CSV with an <strong>email</strong> column. Optional: name, first_name, last_name, company, company_name, title, industry.</p><label for="csv-file">CSV file</label><input id="csv-file" name="file" type="file" accept=".csv,text/csv" required><p id="form-error" class="error" role="alert"></p><div class="form-actions"><button type="button" onclick="downloadSample()">Download sample</button><button class="primary">Import leads</button></div></form>`,async d=>{try{let rows=csvRows((await d.get('file').text()).replace(/^\uFEFF/,'')),headers=rows.shift()?.map(x=>x.trim().toLowerCase());if(!headers?.includes('email'))throw Error('The CSV needs an email column.');let created=0,skipped=0,invalid=0;for(let [i,r] of rows.entries()){let v=Object.fromEntries(headers.map((h,j)=>[h,(r[j]||'').trim()]));v.email=v.email.toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email)){invalid++;continue}if(state.leads.some(l=>l.email.toLowerCase()===v.email)){skipped++;continue}state.leads.push({id:Date.now()+i,name:v.name||[v.first_name,v.last_name].filter(Boolean).join(' ')||v.email.split('@')[0],email:v.email,company:v.company||v.company_name||'Unknown company',title:v.title||'Not provided',industry:v.industry||'Not provided',status:'New',confidence:0});created++}record(`${created} leads imported`);$('#modal').close();render();toast(`Import complete: ${created} added, ${skipped} duplicates skipped, ${invalid} invalid rows.`)}catch(e){$('#form-error').textContent=e.message}})}
function download(name,text,type='text/csv'){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadSample(){download('salesway-sample.csv','name,email,company,title,industry\nAlex Morgan,alex@sample.example,Sample Studio,Founder,Design\n')}
function exportLeads(){let quote=x=>'"'+String(x).replace(/"/g,'""')+'"';download('salesway-leads.csv','name,email,company,title,industry,status\n'+state.leads.map(l=>[l.name,l.email,l.company,l.title,l.industry,l.status].map(quote).join(',')).join('\n'));toast('Lead export downloaded.')}
function exportReport(){download('salesway-demo-report.json',JSON.stringify({demo:true,campaigns:state.campaigns,meetings:state.meetings,activity:state.activity},null,2),'application/json')}
function resetDemo(){modal('Start fresh?',`<p>This clears your local changes and restores the original sample workspace.</p><div class="actions"><button onclick="$('#modal').close()">Keep changes</button><button class="primary" onclick="state=structuredClone(seed);save();selectedThread=0;$('#modal').close();render();toast('Demo workspace reset.')">Reset demo</button></div>`)}
let themePreference='porcelain';try{let saved=localStorage.getItem('salesway-theme');if(['porcelain','midnight','system'].includes(saved))themePreference=saved}catch(e){}
const systemAppearance=matchMedia('(prefers-color-scheme:dark)');
function applyTheme(t){themePreference=t;const resolved=t==='system'?(systemAppearance.matches?'midnight':'porcelain'):t;document.documentElement.dataset.theme=resolved;try{localStorage.setItem('salesway-theme',t)}catch(e){}$('meta[name="theme-color"]').content=resolved==='midnight'?'#111522':'#f3f4f8';document.querySelectorAll('button[data-theme]').forEach(b=>{b.classList.toggle('selected',b.dataset.theme===t);b.setAttribute('aria-pressed',String(b.dataset.theme===t))})}
systemAppearance.addEventListener('change',()=>{if(themePreference==='system')applyTheme('system')});document.querySelectorAll('.themes button').forEach(b=>b.onclick=()=>applyTheme(b.dataset.theme));applyTheme(themePreference);
function drawer(open){$('#sidebar').classList.toggle('open',open);$('#shade').classList.toggle('open',open);$('#menu').setAttribute('aria-expanded',String(open));if(open){$('#sidebar').inert=false;setTimeout(()=>{if($('#sidebar').classList.contains('open'))$('#close-menu').focus()},260);$('#main').inert=true;document.body.style.overflow='hidden'}else{$('#main').inert=false;document.body.style.overflow='';if(innerWidth<=900)$('#sidebar').inert=true;$('#menu').focus()}}
$('#menu').onclick=()=>drawer(true);$('#close-menu').onclick=()=>drawer(false);$('#shade').onclick=()=>drawer(false);document.addEventListener('keydown',e=>{if(!$('#sidebar').classList.contains('open'))return;if(e.key==='Escape')drawer(false);if(e.key==='Tab'){let links=[...$('#sidebar').querySelectorAll('a,button')].filter(x=>x.offsetParent!==null),first=links[0],last=links.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});function responsiveNav(){if(innerWidth>900){$('#main').inert=false;$('#sidebar').inert=false;$('#sidebar').classList.remove('open');$('#shade').classList.remove('open');document.body.style.overflow='';$('#menu').setAttribute('aria-expanded','false')}else if(!$('#sidebar').classList.contains('open'))$('#sidebar').inert=true}addEventListener('resize',responsiveNav);responsiveNav();
function bindTilt(){if(!matchMedia('(hover:hover) and (pointer:fine)').matches||matchMedia('(prefers-reduced-motion:reduce)').matches)return;document.querySelectorAll('.tilt').forEach(c=>{c.onpointermove=e=>{let r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;c.style.transform=`perspective(1000px) rotateX(${-y*9}deg) rotateY(${x*9}deg)`};c.onpointerleave=()=>c.style.transform=''})}
addEventListener('hashchange',()=>{if($('#sidebar').classList.contains('open'))drawer(false);render();scrollTo(0,0);$('#main').focus({preventScroll:true})});addEventListener('scroll',()=>document.querySelector('header').classList.toggle('scrolled',scrollY>10),{passive:true});history.scrollRestoration='manual';scrollTo(0,0);render();setTimeout(()=>{$('#intro').style.opacity='0';$('#intro').style.pointerEvents='none';setTimeout(()=>$('#intro').remove(),700)},3000);
