$('#collapse').onclick=()=>{const collapsed=document.body.classList.toggle('collapsed');$('#collapse').setAttribute('aria-expanded',String(!collapsed));$('#collapse').setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');try{localStorage.setItem('salesway-collapsed',String(collapsed))}catch(e){}};try{if(localStorage.getItem('salesway-collapsed')==='true')document.body.classList.add('collapsed')}catch(e){}
function openSearch(){modal('Find your next step',`<label for="workspace-search">Search contacts, companies, or pages</label><input id="workspace-search" placeholder="Type a name or page…"><div class="search-results" id="search-results"></div>`);let input=$('#workspace-search');input.oninput=()=>{let q=input.value.trim().toLowerCase();$('#search-results').innerHTML=q?[...pages.filter(p=>names[p].toLowerCase().includes(q)).map(p=>`<button onclick="closeModal();location.hash='${p}'">${icon(p)}${names[p]}<small>Page ↗</small></button>`),...state.leads.filter(l=>`${l.name} ${l.company} ${l.email}`.toLowerCase().includes(q)).map(l=>`<button onclick="$('#modal').close();leadDetail(${l.id})">${person(l)}<small>Contact ↗</small></button>`)].join('')||'<p>No matches. Try another name or company.</p>':'<p>Start typing to search this demo workspace.</p>'};input.oninput();input.focus()}
function notifications(){modal('Your workspace, at a glance',`<div class="activity"><span class="icon-tile">${icon('inbox')}</span><div><h3>${state.messages.length} conversations</h3><p>Review interested contacts and plan your next step.</p><button class="link" onclick="closeModal();location.hash='inbox'">Open inbox ↗</button></div></div><div class="activity"><span class="icon-tile">${icon('emails')}</span><div><h3>${state.drafts.filter(d=>d.status==='Needs review').length} drafts to review</h3><p>Every message stays in your hands.</p><button class="link" onclick="closeModal();location.hash='emails'">Review drafts ↗</button></div></div>`)}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#modal').open)openSearch()}});
