function closeCalendar(restore=false){if(calendarPanel){calendarPanel.remove();calendarPanel=null}if(calendarTrigger){calendarTrigger.setAttribute('aria-expanded','false');if(restore)calendarTrigger.focus();calendarTrigger=null}}
function enhanceDates(root=document){root.querySelectorAll('input[type="date"]:not(.date-input-source)').forEach(input=>{const label=input.labels?.[0]?.textContent||'Date';let wrapper=document.createElement('div');wrapper.className='date-control';input.parentNode.insertBefore(wrapper,input);wrapper.appendChild(input);input.classList.add('date-input-source');input.tabIndex=-1;input.setAttribute('aria-hidden','true');let trigger=document.createElement('button');trigger.type='button';trigger.className='date-trigger';trigger.setAttribute('aria-label',label);trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-expanded','false');wrapper.appendChild(trigger);const format=d=>d.toLocaleDateString('en-CA',{year:'numeric',month:'2-digit',day:'2-digit'});function sync(){trigger.innerHTML=`<span class="${input.value?'':'date-placeholder'}">${input.value?esc(new Date(input.value+'T12:00:00').toLocaleDateString('en',{day:'numeric',month:'short',year:'numeric'})):'Choose a date'}</span>${icon('meetings')}`}sync();input.addEventListener('change',sync);input.addEventListener('invalid',()=>{trigger.focus();trigger.style.borderColor='var(--danger)';toast('Choose a valid date before saving.')});function open(){if(calendarTrigger===trigger){closeCalendar(true);return}closeCalendar();closeDropdown();calendarTrigger=trigger;trigger.setAttribute('aria-expanded','true');let chosen=input.value?new Date(input.value+'T12:00:00'):new Date(),year=chosen.getFullYear(),month=chosen.getMonth(),panel=document.createElement('div');calendarPanel=panel;panel.className='calendar';panel.setAttribute('role','dialog');panel.setAttribute('aria-label',label+' calendar');const host=input.closest('dialog')||document.body;host.appendChild(panel);function position(){let r=trigger.getBoundingClientRect(),base=host===document.body?{left:0,top:0,bottom:innerHeight,right:innerWidth}:host.getBoundingClientRect(),height=panel.offsetHeight,width=panel.offsetWidth;let top=base.bottom-r.bottom<height+10&&r.top-base.top>height?r.top-height-8:r.bottom+8;panel.style.left=Math.max(8,Math.min(r.left-base.left,base.right-base.left-width-8))+'px';panel.style.top=Math.max(8,top-base.top)+'px'}function choose(date){const value=format(date);if(input.min&&value<input.min||input.max&&value>input.max)return;input.value=value;trigger.style.borderColor='';sync();closeCalendar(true);input.dispatchEvent(new Event('change',{bubbles:true}))}function draw(){let first=new Date(year,month,1),days=new Date(year,month+1,0).getDate(),offset=(first.getDay()+6)%7,today=format(new Date());panel.innerHTML=`<div class="calendar-header"><button type="button" aria-label="Previous month"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg></button><strong aria-live="polite">${first.toLocaleDateString('en',{month:'long',year:'numeric'})}</strong><button type="button" aria-label="Next month"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m10 6 6 6-6 6"/></svg></button></div><div class="calendar-grid">${['Mo','Tu','We','Th','Fr','Sa','Su'].map(x=>`<span class="calendar-weekday">${x}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=new Date(year,month,i+1),value=format(d),disabled=(input.min&&value<input.min)||(input.max&&value>input.max);return `<button type="button" class="calendar-day ${value===today?'today':''} ${value===input.value?'selected':''}" data-day="${i+1}" aria-label="${d.toLocaleDateString('en',{day:'numeric',month:'long',year:'numeric'})}" aria-pressed="${value===input.value}" ${disabled?'disabled':''}>${i+1}</button>`}).join('')}</div><div class="calendar-footer"><button type="button" data-today>Today</button><small>Use arrow keys to navigate</small><button type="button" data-close>Close</button></div>`;const buttons=panel.querySelectorAll('.calendar-header button');buttons[0].onclick=()=>{month--;if(month<0){month=11;year--}draw();panel.querySelector('.calendar-header button').focus()};buttons[1].onclick=()=>{month++;if(month>11){month=0;year++}draw();panel.querySelectorAll('.calendar-header button')[1].focus()};panel.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>choose(new Date(year,month,Number(b.dataset.day))));panel.querySelector('[data-today]').onclick=()=>choose(new Date());panel.querySelector('[data-today]').disabled=!!((input.min&&today<input.min)||(input.max&&today>input.max));panel.querySelector('[data-close]').onclick=()=>closeCalendar(true);position()}panel.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeCalendar(true);return}if(e.target.matches('[data-day]')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();let day=Number(e.target.dataset.day),change={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7}[e.key];let next=e.key==='Home'?1:e.key==='End'?new Date(year,month+1,0).getDate():day+change;let d=new Date(year,month,next);year=d.getFullYear();month=d.getMonth();draw();panel.querySelector(`[data-day="${d.getDate()}"]:not(:disabled)`)?.focus()}if(e.key==='Tab'){let list=[...panel.querySelectorAll('button:not(:disabled)')],i=list.indexOf(document.activeElement);if(e.shiftKey&&i===0){e.preventDefault();list.at(-1).focus()}else if(!e.shiftKey&&i===list.length-1){e.preventDefault();list[0].focus()}}};draw();(panel.querySelector('.selected:not(:disabled)')||panel.querySelector('.today:not(:disabled)')||panel.querySelector('.calendar-day:not(:disabled)')||panel.querySelector('button')).focus()}trigger.onclick=open;trigger.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();open()}}})}
document.addEventListener('pointerdown',e=>{if(calendarPanel&&!calendarPanel.contains(e.target)&&!calendarTrigger?.contains(e.target))closeCalendar()});addEventListener('resize',()=>closeCalendar());addEventListener('hashchange',()=>closeCalendar());
